package com.panish.ridebooking.ride.service;
import com.fasterxml.jackson.core.JsonProcessingException; import com.fasterxml.jackson.databind.ObjectMapper; import com.panish.ridebooking.events.*; import com.panish.ridebooking.ride.domain.*; import com.panish.ridebooking.ride.repository.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.UUID;
@Service public class RideEventService {private final RideRepository rides;private final ProcessedEventRepository processed;private final OutboxEventRepository outbox;private final ObjectMapper mapper;public RideEventService(RideRepository r,ProcessedEventRepository p,OutboxEventRepository o,ObjectMapper m){rides=r;processed=p;outbox=o;mapper=m;} @Transactional public void handleRequest(RideRequestedEvent event){if(event.eventId()==null||processed.existsById(event.eventId()))return;double distance=estimateDistance(event.pickup(),event.dropoff());double fare=Math.round((50.0+distance*12.0)*100.0)/100.0;Ride ride=rides.save(new Ride(event.riderId(),event.pickup(),event.dropoff(),fare));RideCreatedEvent created=new RideCreatedEvent(UUID.randomUUID().toString(),ride.getId(),ride.getRiderId(),ride.getEstimatedFare());saveOutbox(created.eventId(),"ride-created-topic",created);processed.save(new ProcessedEvent(event.eventId()));} @Transactional public void handleAssignmentFailed(DriverAssignmentFailedEvent event){if(event.eventId()!=null&&processed.existsById(event.eventId()))return;rides.findById(event.rideId()).ifPresent(Ride::cancelNoDrivers);if(event.eventId()!=null)processed.save(new ProcessedEvent(event.eventId()));} @Transactional public void handleAssigned(DriverAssignedEvent event){rides.findById(event.rideId()).ifPresent(r->r.assign(event.driverId(),event.driverName()));} private double estimateDistance(String pickup,String dropoff){return Math.max(1.0,Math.abs(pickup.toLowerCase().hashCode()-dropoff.toLowerCase().hashCode())%2500/100.0);} private void saveOutbox(String id,String topic,Object event){try{outbox.save(new OutboxEvent(id,topic,mapper.writeValueAsString(event)));}catch(JsonProcessingException e){throw new IllegalStateException("Could not serialize event",e);}}}